typedef unsigned int u_int;
typedef unsigned int nslSourceId;
typedef int nslSoundParamEnum;

void *operator new(unsigned int, unsigned int, const char *, int);
#define NEW new(0, __FILE__, 0)
#define MENUSOUND_MAXSOURCES 32
#define MENUSOUND_MAXLABELCHAR 32
#define NSL_INVALID_ID 0
#define NSL_SOUNDPARAM_VOLUME 0

class Menu;
class MenuSystem;
class MenuEntry;
typedef MenuEntry *pMenuEntry;
typedef bool (*pMenuEntryButtonFunction)(MenuEntry *, int);

class stringx {
    char *chars;
    void *my_buf;
public:
    ~stringx();
    const char *c_str() const { return chars; }
};

class MenuEntry {
    unsigned int flags;
public:
    MenuEntry() { flags = 3; }
    virtual ~MenuEntry();
    virtual void dummy();
};
class MenuEntryLabel : public MenuEntry {
protected:
    const char *label;
public:
    MenuEntryLabel(const char *t) { label = t; }
    virtual ~MenuEntryLabel();
};
class MenuEntryFunction : public MenuEntryLabel {
    pMenuEntryButtonFunction fn;
public:
    MenuEntryFunction(char *t, pMenuEntryButtonFunction f) : MenuEntryLabel(t) { fn = f; }
    virtual ~MenuEntryFunction();
};
class MenuEntryFunctionFloatEdit : public MenuEntryLabel {
    float *tfloat;
protected:
    float lo, hi, step;
    char *format;
    pMenuEntryButtonFunction fn;
public:
    virtual void SetValue(float n) { *tfloat = n; }
};
class SoundMenuEntryFunctionFloatEdit : public MenuEntryFunctionFloatEdit {
public:
    nslSourceId src;
    unsigned int snd;
    SoundMenuEntryFunctionFloatEdit(char *, float *, pMenuEntryButtonFunction, nslSourceId, float, float, float);
};
class Menu {
    Menu *parent;
    int entries;
    pMenuEntry *entry;
    int activeentry;
    bool isopen;
    Menu *closeto;
    MenuSystem *control;
public:
    virtual ~Menu();
    void ClearMenu();
    void AddEntry(pMenuEntry);
    virtual void OnOpen(Menu *, MenuSystem *);
};
class MenuRender { public: void Refresh(); };
class MenuSystem : public MenuRender {};
class MenuSoundDraw : public Menu { public: void OnOpen(Menu *, MenuSystem *); };

extern float MENUSOUND_SourceVols[32];
extern nslSourceId MENUSOUND_Sources[32];
extern char MENUDRAW_SourceLabels[32][32];
extern SoundMenuEntryFunctionFloatEdit *MENUSOUND_SourceEntries[32];
extern MenuEntryFunction *DumpFunc;
extern bool Dump(MenuEntry *, int);
extern bool Play(MenuEntry *, int);
extern stringx MENUSOUND_SourceLabel(nslSourceId);
extern void nslPauseAllSounds();
extern nslSourceId nslGetSourceByIndex(int);
extern void mem_lock_malloc(bool);
extern float nslGetSourceParam(nslSourceId, nslSoundParamEnum);
extern int sprintf(char *, const char *, ...);
extern int printf(const char *, ...);

void MenuSoundDraw::OnOpen(Menu *cto, MenuSystem *c)
{
    nslPauseAllSounds();
    u_int mecount = 0;
    nslSourceId src = nslGetSourceByIndex(mecount);

    mem_lock_malloc(false);

    ClearMenu();

    DumpFunc = NEW MenuEntryFunction("Dump Values", Dump);
    AddEntry(DumpFunc);
    bool stop = false;
    while(src != NSL_INVALID_ID && !stop)
    {
        MENUSOUND_Sources[mecount] = src;

        stringx label = MENUSOUND_SourceLabel(src);
        sprintf(MENUDRAW_SourceLabels[mecount], label.c_str());

        MENUSOUND_SourceEntries[mecount] = NEW SoundMenuEntryFunctionFloatEdit(MENUDRAW_SourceLabels[mecount], MENUSOUND_SourceVols + mecount, Play,src, 0.0f, 1.0f, .05f);
        MENUSOUND_SourceEntries[mecount]->SetValue(nslGetSourceParam(src, NSL_SOUNDPARAM_VOLUME));

        AddEntry(MENUSOUND_SourceEntries[mecount]);

        ++mecount;
        if (mecount >= MENUSOUND_MAXSOURCES)
        {
            printf("MENUDRAW:\tToo many entities for draw menu.  Skipping the rest...\n");
            stop = true;
        }
        src = nslGetSourceByIndex(mecount);
    }

    mem_lock_malloc(true);
    c->Refresh();

    Menu::OnOpen(cto, c);
}
